var groups = {
    "A": "\u63de\u9feb\u554a\u963f\u5416\u9515\u7231\u827e\u54ce\u5509\u54c0\u6328\u57c3\u77ee\u788d\u66a7\u764c\u853c\u9698\u7691\u972d\u55f3\u5ad2\u6bd0\u53c6\u7477\u7839\u953f\u55cc\u6309\u5b89\u6697\u6848\u5cb8\u4ffa\u9eef\u5eb5\u978d\u8c19\u6c28\u80fa\u9e4c\u6849\u72b4\u5535\u94f5\u57ef\u76e6\u57b5\u6602\u80ae\u76ce\u536c\u50b2\u5965\u71ac\u6556\u6fb3\u51f9\u61ca\u55f7\u62d7\u8884\u9ccc\u7ff1\u7352\u9a9c\u5773\u93d6\u9068\u5aaa\u87af\u5c99\u7488\u93ca\u8071\u5ed2\u5961\u96a9\u8581\u5d85",
    "B": "\u628a\u5427\u516b\u7238\u5df4\u7f62\u62d4\u9738\u75a4\u8dcb\u6252\u53ed\u82ad\u9776\u575d\u8019\u7b06\u9b43\u7c91\u94af\u705e\u634c\u9c85\u5c9c\u9c83\u83dd\u8686\u80c8\u7f93\u59ad\u6733\u767d\u767e\u8d25\u6446\u62dc\u67cf\u63b0\u4f2f\u4f70\u7a17\u636d\u5457\u64d8\u534a\u529e\u822c\u677f\u73ed\u4f34\u7248\u642c\u626e\u6591\u6273\u74e3\u7eca\u9881\u62cc\u962a\u5742\u7622\u94a3\u764d\u653d\u67c8\u6604\u6e74\u977d\u5e2e\u8180\u90a6\u68d2\u7ed1\u699c\u508d\u78c5\u6886\u9551\u8c24\u868c\u6d5c\u84a1\u73a4\u585d\u6412\u4fdd\u62a5\u5305\u5b9d\u62b1\u66b4\u7206\u8584\u5821\u9971\u8c79\u80de\u5265\u9c8d\u8912\u5228\u82de\u9e28\u66dd\u7172\u8446\u96f9\u8913\u9f85\u5b62\u8db5\u67b9\u88ab\u5907\u5317\u80cc\u676f\u8f88\u60b2\u8d1d\u500d\u5351\u60eb\u7891\u72c8\u84d3\u6096\u5b5b\u7119\u90b6\u9642\u94a1\u8919\u789a\u97b4\u943e\u9e4e\u68d3\u7cd2\u7432\u6911\u81c2\u9781\u672c\u5954\u7b28\u8d32\u82ef\u951b\u755a\u7287\u574c\u5034\u681f\u5d29\u8e66\u7ef7\u8ff8\u752d\u5623\u6cf5\u955a\u750f\u742b\u794a\u6bd4\u5fc5\u6bd5\u7b14\u907f\u95ed\u9f3b\u903c\u5c44\u58c1\u5f7c\u78a7\u5e01\u965b\u9119\u853d\u5315\u6bd9\u8f9f\u5a62\u5f0a\u74a7\u5e87\u655d\u75f9\u5f3c\u4ffe\u88e8\u859c\u54d4\u610e\u5421\u8df8\u59a3\u7be6\u835c\u72f4\u6bd6\u84d6\u5b16\u7b5a\u9ac0\u8378\u6fde\u7540\u8d51\u79d5\u7b85\u8298\u895e\u82fe\u6ed7\u94cb\u5eb3\u8406\u7695\u5487\u822d\u6c98\u73cc\u89f1\u9cbe\u8bd0\u90b2\u4f56\u999d\u5752\u8fb9\u4fbf\u53d8\u904d\u7f16\u8fa9\u97ad\u8fa8\u6241\u8fab\u8d2c\u8759\u533e\u535e\u6c74\u5f01\u782d\u7178\u890a\u7b3e\u9cca\u662a\u5fed\u82c4\u6283\u78a5\u8439\u8868\u6807\u9556\u5f6a\u98d9\u5a4a\u9aa0\u9573\u8198\u88f1\u6753\u98d1\u4ff5\u9cd4\u647d\u762d\u719b\u85e8\u5126\u9a89\u5e56\u700c\u813f\u522b\u618b\u762a\u9cd6\u8e69\u767f\u5bbe\u5f6c\u658c\u6ee8\u9b13\u7f24\u9554\u6fd2\u69df\u6ba1\u8191\u6448\u73a2\u50a7\u8c73\u90a0\u9acc\u5e76\u5175\u51b0\u75c5\u67c4\u997c\u7980\u79c9\u4e19\u70b3\u6452\u90b4\u663a\u86c3\u6ce2\u535a\u8116\u62e8\u64ad\u52c3\u73bb\u818a\u640f\u9a73\u6cca\u7c38\u5e1b\u94b5\u8ddb\u6e24\u83e0\u7934\u5575\u8236\u535c\u997d\u94c2\u94b9\u7b94\u4eb3\u6a97\u9e41\u50f0\u8e23\u9548\u7835\u9c8c\u54f1\u5d93\u6d61\u999e\u6b02\u8274\u88af\u4e0d\u90e8\u6b65\u5e03\u8865\u6016\u6355\u7c3f\u57d4\u54fa\u57e0\u535f\u900b\u949a\u6661\u74ff\u91ad\u8500\u57d7",
    "C": "\u87cc\u5382\u64e6\u5693\u624d\u83dc\u5f69\u91c7\u8d22\u6750\u731c\u8521\u88c1\u8e29\u776c\u5072\u53c2\u6b8b\u60e8\u9910\u707f\u60ed\u8695\u74a8\u7cb2\u9a96\u9eea\u5b71\u85cf\u82cd\u4ed3\u8231\u6ca7\u4f27\u9e27\u8349\u64cd\u808f\u8279\u66f9\u5608\u7cd9\u69fd\u6f15\u5c6e\u8294\u825a\u87ac\u6d4b\u4fa7\u518c\u7b56\u5395\u607b\u5c91\u6d94\u66fe\u5c42\u8e6d\u564c\u5d92\u5dee\u67e5\u5bdf\u8336\u63d2\u8be7\u53c9\u5c94\u832c\u8869\u78b4\u59f9\u6748\u643d\u6aab\u69ce\u6c4a\u9572\u9538\u9987\u579e\u4f98\u7339\u8e45\u5d56\u62c6\u67f4\u9497\u8c7a\u4faa\u831d\u867f\u7625\u4ea7\u98a4\u7f20\u7985\u8749\u6400\u94f2\u5a75\u63ba\u9610\u5fcf\u998b\u6f7a\u87fe\u8c04\u8c17\u5181\u6fb6\u89c7\u9561\u7fbc\u5edb\u5dc9\u8487\u97c2\u8e94\u522c\u6d50\u895c\u700d\u9aa3\u9575\u65f5\u5574\u68b4\u5133\u8fbf\u957f\u5e38\u573a\u5531\u5c1d\u660c\u7545\u80a0\u507f\u655e\u6005\u5021\u5a3c\u5ae6\u7316\u6636\u5f9c\u6c05\u4f25\u83d6\u82cc\u960a\u9b2f\u60dd\u9cb3\u9cbf\u8d85\u671d\u6f6e\u5435\u5632\u6284\u7092\u5de2\u949e\u6641\u712f\u8016\u600a\u5f28\u7ef0\u8f66\u5f7b\u626f\u64a4\u6f88\u63a3\u7817\u577c\u5c3a\u6c89\u9648\u81e3\u6668\u5c18\u8d81\u8fb0\u886c\u55d4\u741b\u79f0\u5bb8\u5ff1\u62bb\u789c\u8c0c\u8c36\u90f4\u68fd\u778b\u6987\u9f80\u75a2\u68a3\u7141\u6210\u57ce\u7a0b\u627f\u8bda\u76db\u4e58\u6491\u5448\u60e9\u4e1e\u6f84\u901e\u6a59\u9a8b\u77a0\u79e4\u94d6\u584d\u7424\u88ce\u6f82\u57d5\u67fd\u86cf\u9172\u67a8\u73f5\u8d6a\u5041\u5bac\u725a\u73f9\u6195\u5eb1\u5403\u6301\u8fdf\u8d64\u75f4\u6c60\u9f7f\u65a5\u9a70\u803b\u7fc5\u54e7\u70bd\u55e4\u86a9\u53f1\u5f1b\u4f88\u557b\u6555\u87ad\u9b51\u996c\u7b1e\u8e1f\u5880\u8c49\u5ab8\u892b\u9e31\u5f73\u830c\u7bea\u761b\u645b\u7735\u50ba\u6f26\u80e3\u74fb\u75d3\u51b2\u5145\u866b\u5d07\u5ba0\u5fe1\u61a7\u94f3\u8202\u825f\u7fc0\u833a\u73eb\u6f34\u644f\u62bd\u4ec7\u81ed\u4e11\u6101\u7b79\u7785\u916c\u7ef8\u7574\u8e0c\u60c6\u7a20\u4fe6\u96e0\u7633\u72a8\u4fb4\u5e31\u677b\u6906\u51fa\u5904\u695a\u9664\u521d\u89e6\u53a8\u7840\u50a8\u755c\u891a\u6410\u6a71\u8e87\u96cf\u9504\u77d7\u6775\u696e\u6035\u9edc\u7ecc\u870d\u520d\u6ec1\u6a17\u8e70\u61b7\u4e8d\u4ff6\u65b6\u6474\u6fcb\u7421\u63e3\u8e39\u640b\u555c\u4f20\u7a7f\u8239\u5ddd\u5598\u4e32\u948f\u693d\u821b\u9044\u6c1a\u5e8a\u7a97\u521b\u75ae\u95ef\u6006\u5647\u5439\u5782\u9524\u6376\u708a\u69cc\u9672\u68f0\u5015\u570c\u6625\u7eaf\u5507\u8822\u6df3\u9187\u693f\u9e51\u83bc\u877d\u583e\u7443\u6233\u9f8a\u8f8d\u8e14\u60d9\u9034\u6b64\u6b21\u523a\u8bcd\u8f9e\u6148\u8d50\u78c1\u4f3a\u74f7\u8328\u96cc\u7960\u5472\u75b5\u6cda\u7ccd\u9e5a\u8308\u8dd0\u73bc\u4f7d\u83bf\u4ece\u5306\u806a\u4e1b\u8471\u742e\u6dd9\u56f1\u9aa2\u82c1\u679e\u7481\u719c\u60b0\u51d1\u8f8f\u8160\u7c97\u4fc3\u918b\u7c07\u731d\u8e59\u8e74\u5f82\u9162\u6b82\u851f\u7a9c\u8e7f\u7be1\u64ba\u6c46\u7228\u9569\u8106\u50ac\u7fe0\u5d14\u6467\u7cb9\u60b4\u7480\u5550\u8403\u7601\u6dec\u69b1\u6bf3\u6f3c\u7f1e\u5b58\u6751\u5bf8\u5fd6\u76b4\u90a8\u9519\u63aa\u632b\u6413\u64ae\u78cb\u8e49\u9509\u539d\u77ec\u5d6f\u75e4\u9e7e\u811e\u7473\u68e4\u839d",
    "D": "\u9fd5\u6c39\u5355\u94db\u8e72\u5927\u6253\u7b54\u8fbe\u642d\u54d2\u7629\u55d2\u6c93\u8037\u9791\u977c\u59b2\u8921\u8df6\u601b\u7b2a\u57af\u6e9a\u709f\u8359\u9fce\u5e26\u4ee3\u5f85\u5446\u888b\u6234\u9edb\u6b79\u8d37\u902e\u6020\u6b86\u5cb1\u73b3\u5454\u50a3\u8fe8\u7ed0\u53c7\u57ed\u9a80\u8f6a\u5788\u4f46\u6de1\u62c5\u5f39\u4e39\u86cb\u80c6\u65e6\u8bde\u803d\u60ee\u7708\u4e3c\u6fb9\u63b8\u90f8\u6b9a\u5556\u6c2e\u510b\u8043\u7baa\u4eb6\u75b8\u840f\u7605\u758d\u8d55\u61ba\u5f53\u515a\u8361\u6321\u6863\u88c6\u5b95\u7800\u73f0\u51fc\u8c20\u57b1\u83ea\u7b5c\u5230\u5012\u9053\u5200\u5bfc\u5c9b\u76d7\u53e8\u8e48\u7977\u6363\u7a3b\u60bc\u7e9b\u5fc9\u6c18\u636f\u9c7d\u8220\u7684\u5730\u5f97\u5fb7\u561a\u951d\u5e95\u627d\u7b49\u706f\u767b\u77aa\u9093\u51f3\u8e6c\u5654\u956b\u78f4\u6225\u5d9d\u7492\u7b2c\u5f1f\u4f4e\u5e1d\u654c\u62b5\u9012\u8fea\u6ef4\u8482\u72c4\u7b1b\u5600\u5824\u90b8\u5ae1\u68e3\u7f14\u8c1b\u6da4\u837b\u5a23\u8bcb\u6c10\u7825\u955d\u7747\u577b\u67e2\u97ae\u7f9d\u89cc\u7c74\u9ab6\u78b2\u7998\u8e36\u83c2\u9ae2\u7393\u6755\u830b\u8e62\u5a82\u55f2\u70b9\u7535\u5e97\u6bbf\u5178\u98a0\u57ab\u7538\u60e6\u5960\u6382\u766b\u5dc5\u6dc0\u6ec7\u73b7\u8e2e\u4f43\u975b\u7898\u94bf\u7c1f\u765c\u576b\u963d\u6242\u7414\u6389\u8c03\u5c4c\u96d5\u540a\u9493\u5201\u53fc\u8c82\u51cb\u7889\u9cb7\u94eb\u94de\u7a8e\u6c48\u7239\u8776\u8dcc\u53e0\u789f\u8fed\u8c0d\u558b\u7252\u581e\u800b\u9cbd\u6633\u8e40\u74de\u57a4\u7ed6\u696a\u5b9a\u9876\u4e01\u76ef\u8ba2\u53ee\u9f0e\u9489\u952d\u753a\u4ec3\u914a\u815a\u738e\u7887\u7594\u5576\u8035\u8423\u4e22\u94e5\u52a8\u4e1c\u6d1e\u61c2\u51ac\u8463\u51bb\u680b\u549a\u5cd2\u80f4\u4f97\u606b\u9e2b\u578c\u7850\u6c21\u80e8\u5cbd\u90fd\u6597\u6296\u8c46\u9017\u515c\u9661\u7aa6\u75d8\u86aa\u8538\u7bfc\u94ad\u8bfb\u5ea6\u72ec\u6bd2\u675c\u809a\u8d4c\u7763\u6e21\u561f\u5835\u5992\u7779\u7b03\u6e0e\u9540\u728a\u724d\u8839\u9ee9\u9607\u828f\u691f\u9ad1\u53be\u987f\u65ad\u6bb5\u77ed\u7aef\u953b\u7f0e\u7145\u6934\u8011\u7c16\u5845\u7456\u5bf9\u961f\u5806\u5151\u603c\u7893\u794b\u6566\u9566\u76fe\u6c8c\u9041\u5428\u949d\u58a9\u7096\u76f9\u60c7\u8db8\u7905\u8e7e\u696f\u7818\u591a\u8eb2\u6735\u593a\u5815\u54c6\u8dfa\u8e31\u8235\u5484\u5241\u94ce\u60f0\u579b\u6387\u54da\u88f0\u57f5\u9973\u4eb8\u525f",
    "E": "\u8bf6\u5940\u97a5\u55ef\u6b38\u997f\u5443\u6076\u989d\u4fc4\u6115\u9e45\u5669\u5a25\u5384\u5ce8\u9102\u904f\u627c\u9cc4\u86fe\u5a40\u8bb9\u960f\u9537\u989a\u9e57\u843c\u5c59\u8c14\u57a9\u816d\u83aa\u8f6d\u82ca\u9507\u5d3f\u59f6\u6d90\u5828\u6069\u6441\u84bd\u800c\u513f\u4e8c\u5c14\u8033\u9975\u8fe9\u8d30\u6d31\u73e5\u94d2\u9e38\u9651\u9c95\u54a1\u800f",
    "F": "\u8985\u9cc6\u4f5b\u8543\u53d1\u6cd5\u7f5a\u4e4f\u4f10\u9600\u7b4f\u781d\u73d0\u57a1\u7ffb\u53cd\u996d\u70e6\u51e1\u72af\u8303\u756a\u7e41\u8fd4\u6cdb\u5e06\u8d29\u6a0a\u85e9\u68b5\u5e61\u8629\u74a0\u77fe\u7548\u71d4\u9492\u6c3e\u8e6f\u58a6\u653e\u623f\u9632\u65b9\u4eff\u82b3\u8bbf\u59a8\u574a\u7eba\u80aa\u822b\u678b\u6609\u9c82\u90a1\u94ab\u8684\u7265\u98de\u975e\u8d39\u83f2\u5e9f\u5983\u80a5\u5561\u532a\u6cb8\u80ba\u7eef\u6590\u970f\u7fe1\u6249\u5420\u8bfd\u871a\u72d2\u8153\u60b1\u6ddd\u82be\u75f1\u69a7\u9cb1\u7bda\u670f\u68d0\u9544\u5255\u5206\u4efd\u7eb7\u594b\u6124\u7c89\u6c1b\u5429\u82ac\u711a\u575f\u5fff\u7caa\u6c7e\u915a\u68fc\u507e\u9cbc\u68fb\u9f22\u7fc2\u7035\u574b\u8c6e\u98ce\u5c01\u51e4\u5cf0\u75af\u950b\u67ab\u4e30\u5949\u51af\u7f1d\u9022\u8bbd\u8702\u70fd\u4ff8\u6ca3\u6ca8\u9146\u8451\u552a\u781c\u8d57\u5d36\u6d72\u5426\u7f36\u670d\u592b\u7236\u590d\u798f\u5e9c\u526f\u8d1f\u4ed8\u5bcc\u5987\u9644\u4f0f\u5085\u6d6e\u6276\u629a\u7b26\u80a4\u8179\u5e45\u5490\u8986\u8150\u5f17\u8d74\u65a7\u4fef\u8d4b\u8f85\u8299\u62c2\u752b\u4fd8\u7f1a\u8760\u6577\u812f\u88b1\u8151\u8f90\u5b5a\u9a78\u91dc\u82fb\u5310\u5b93\u961c\u5b75\u99a5\u8300\u6daa\u832f\u51eb\u86a8\u62ca\u876e\u8ba3\u9efc\u8dba\u602b\u6c1f\u8709\u9efb\u9eb8\u7ec2\u8dd7\u9c8b\u7f58\u6ecf\u90db\u83d4\u6874\u5e5e\u7953\u544b\u7ecb\u83a9\u8d59\u911c\u82a3\u6d11\u7c20\u6991\u7a03\u97e8\u739e\u7806\u57ba\u7408",
    "G": "\u9fd4\u5e7f\u5c2c\u560e\u4f3d\u5676\u65ee\u5c15\u5c1c\u9486\u80f3\u8be5\u6539\u76d6\u6982\u4e10\u9499\u6e89\u8d45\u5793\u9654\u6224\u8344\u6650\u611f\u5e72\u6562\u8d76\u7518\u5c34\u6746\u809d\u7aff\u6a44\u8d63\u79c6\u67d1\u64c0\u7395\u6de6\u6cd4\u77f8\u5769\u7ec0\u82f7\u65f0\u75b3\u9150\u6f89\u8677\u9ce1\u521a\u6e2f\u94a2\u5c97\u5188\u7f38\u7eb2\u7f61\u6760\u809b\u7b7b\u51ae\u77fc\u583d\u6206\u9fcd\u9ad8\u544a\u641e\u7cd5\u7a3f\u818f\u7f94\u768b\u9550\u777e\u7bd9\u8bf0\u69c1\u6772\u7f1f\u9506\u90dc\u85c1\u69d4\u7b76\u4e2a\u54e5\u5404\u683c\u6b4c\u9769\u9694\u9601\u845b\u5272\u6208\u6401\u9e3d\u7599\u9abc\u55dd\u784c\u54af\u94ec\u9b32\u572a\u8238\u8188\u867c\u88bc\u54ff\u9549\u4ee1\u9979\u5865\u6ec6\u7ed9\u8ddf\u6839\u4e98\u826e\u54cf\u831b\u66f4\u803f\u54fd\u8015\u7fb9\u5e9a\u6897\u8d53\u57c2\u9ca0\u7cb3\u7ee0\u6d6d\u6685\u9e52\u516c\u5de5\u529f\u653b\u5bab\u5171\u4f9b\u606d\u5f13\u8d21\u8eac\u62f1\u9f9a\u5de9\u86a3\u89e5\u6c5e\u80b1\u73d9\u7854\u591f\u72d7\u6784\u52fe\u8d2d\u6c9f\u94a9\u82df\u57a2\u7bdd\u4f5d\u5abe\u67b8\u8bdf\u5f40\u7f11\u9058\u97b2\u7b31\u89cf\u5ca3\u59e4\u96ca\u8007\u53e4\u6545\u987e\u80a1\u59d1\u9aa8\u5b64\u8c37\u9f13\u56fa\u4f30\u5495\u8f9c\u96c7\u86ca\u83c7\u6c69\u7b8d\u9522\u6cbd\u9e58\u81cc\u726f\u8f71\u9e2a\u688f\u75fc\u94b4\u6bc2\u5d2e\u8bc2\u77bd\u83f0\u86c4\u7f96\u89da\u560f\u7f5f\u6996\u9164\u9989\u727f\u580c\u84c7\u9cb4\u5471\u7014\u6302\u74dc\u522e\u5be1\u5366\u8902\u5250\u9e39\u8bd6\u681d\u80cd\u602a\u4e56\u62d0\u63b4\u592c\u5173\u7ba1\u5b98\u89c2\u9986\u60ef\u51a0\u8d2f\u704c\u7f50\u68fa\u500c\u76e5\u63bc\u6dab\u9ccf\u9e73\u74d8\u797c\u742f\u6bcc\u7b66\u8484\u721f\u9ce4\u5149\u901b\u54a3\u72b7\u80f1\u6844\u6d38\u73d6\u5799\u9b3c\u8d35\u89c4\u5f52\u8dea\u67dc\u8be1\u7470\u6842\u9f9f\u8f68\u95fa\u572d\u6867\u523d\u7678\u7845\u59ab\u73ea\u7688\u6677\u9c91\u523f\u9cdc\u59fd\u7c0b\u5e8b\u5b84\u5326\u90bd\u9b36\u7b40\u6eda\u68cd\u886e\u9ca7\u78d9\u8f8a\u7ef2\u8fc7\u56fd\u679c\u90ed\u9505\u88f9\u8748\u8052\u5e3c\u6901\u8662\u57da\u5459\u5d1e\u8158\u9998\u7cbf\u873e\u9983",
    "H": "\u7746\u5475\u592f\u5d45\u86e4\u5408\u7ea5\u988c\u7ea2\u9e44\u54c8\u94ea\u8fd8\u6d77\u5b69\u5bb3\u9a87\u55e8\u9ab8\u4ea5\u55d0\u6c26\u91a2\u80f2\u548d\u6c49\u5bd2\u558a\u97e9\u6c57\u542b\u6db5\u7ff0\u61be\u7f55\u64bc\u608d\u701a\u51fd\u61a8\u65f1\u9163\u9894\u90af\u634d\u9f3e\u6657\u83e1\u710a\u9878\u9097\u7113\u86b6\u625e\u6496\u850a\u7400\u66b5\u57be\u5d21\u6d5b\u884c\u822a\u676d\u6c86\u9883\u7ed7\u597d\u53f7\u6beb\u8c6a\u6d69\u8017\u660a\u90dd\u568e\u7693\u58d5\u55e5\u98a2\u6fe0\u84bf\u704f\u8c89\u869d\u8585\u769e\u6dcf\u5686\u9117\u548c\u4f55\u559d\u6cb3\u8d6b\u6838\u8d3a\u76d2\u8377\u9e64\u79be\u8910\u55ec\u58d1\u9616\u6db8\u52be\u9602\u8bc3\u90c3\u9fa2\u97a8\u7fee\u66f7\u9f81\u76cd\u83cf\u76c9\u9978\u7187\u9e56\u7fef\u578e\u96ba\u9ed1\u563f\u5f88\u72e0\u6068\u75d5\u54fc\u6a2a\u8861\u6052\u4ea8\u8605\u73e9\u59ee\u6841\u9e3b\u583c\u8f70\u6d2a\u8679\u5b8f\u9e3f\u54c4\u5f18\u70d8\u6cd3\u95f3\u8ba7\u85a8\u8a07\u836d\u7eae\u543d\u7ad1\u857b\u7fc3\u9ec9\u551d\u7392\u8c3c\u540e\u5019\u539a\u543c\u4faf\u7334\u5589\u9005\u7bcc\u760a\u9c8e\u5820\u5795\u9f41\u9aba\u7cc7\u90c8\u9c98\u4e4e\u547c\u5ffd\u62a4\u80e1\u864e\u6e56\u7cca\u6237\u4e92\u72d0\u58f6\u8774\u60da\u5f27\u552c\u846b\u6caa\u6248\u745a\u7425\u6d52\u659b\u56eb\u795c\u9190\u553f\u7322\u7b0f\u74e0\u69f2\u6019\u7173\u9e55\u6ef9\u89f3\u5cb5\u70c0\u9120\u623d\u7e20\u51b1\u9e71\u6df4\u6612\u9ce0\u5aed\u8f77\u6608\u8bdd\u82b1\u5316\u534e\u5212\u753b\u6ed1\u54d7\u733e\u6866\u9a85\u5a73\u94e7\u7809\u89df\u574f\u6000\u6dee\u69d0\u5f8a\u8e1d\u6362\u7f13\u73af\u5e7b\u5524\u6b22\u60a3\u7115\u6853\u9b1f\u5ba6\u5bf0\u6d63\u75ea\u6da3\u5942\u571c\u8c62\u737e\u6d39\u5b1b\u7f33\u8411\u9ca9\u90c7\u6f36\u902d\u64d0\u953e\u956e\u6fb4\u9e6e\u8c86\u5cd8\u8341\u9ec4\u7687\u6643\u614c\u8352\u604d\u8c0e\u60f6\u51f0\u714c\u7c27\u5fa8\u8757\u5e4c\u6f62\u749c\u9051\u78fa\u968d\u8093\u6e5f\u87e5\u7bc1\u9cc7\u6ec9\u55a4\u7640\u953d\u824e\u745d\u5a93\u4f1a\u56de\u6325\u7070\u6167\u8f89\u6062\u6bc1\u6094\u60e0\u6c47\u7ed8\u5fbd\u8bb3\u6656\u6666\u8d3f\u79fd\u5349\u9ebe\u8bf2\u8559\u5f57\u8bd9\u5599\u835f\u70e9\u867a\u86d4\u73f2\u54b4\u8334\u605a\u6d04\u8886\u96b3\u7fda\u7fd9\u6d4d\u87ea\u784a\u6a5e\u70e0\u6df7\u5a5a\u9b42\u660f\u6d51\u8364\u9984\u8be8\u960d\u6eb7\u60db\u7888\u6216\u6d3b\u706b\u4f19\u83b7\u60d1\u8d27\u7978\u970d\u8c41\u5925\u56af\u85ff\u956c\u8816\u6509\u94ac\u5684\u952a\u5290\u6fe9\u8020\u6f37\u4f78",
    "J": "\u6ab5\u6718\u7f65\u527f\u621b\u5939\u9888\u53e5\u8d3e\u77dc\u6c3f\u7085\u7ea7\u96c6\u51e0\u53ca\u673a\u8bb0\u5b63\u51fb\u6025\u9e21\u6324\u7cfb\u5373\u65e2\u6781\u8ba1\u6fc0\u7ee7\u57fa\u5bc4\u5fcc\u5df1\u9645\u7eaa\u6280\u6d4e\u8ff9\u5409\u79ef\u5bc2\u75be\u59ec\u7ee9\u796d\u808c\u8f91\u7c4d\u573e\u5993\u5ac9\u9965\u5242\u810a\u7a3d\u53fd\u5527\u8ba5\u85c9\u5180\u621f\u68d8\u7f09\u60b8\u7f81\u7391\u4f0e\u9701\u77f6\u9afb\u7a37\u5c8c\u6c72\u7578\u7b08\u89ca\u9aa5\u5d47\u84df\u7b95\u4f76\u7620\u757f\u7284\u4e9f\u8dfb\u6b9b\u66a8\u9cab\u5048\u9f51\u84ba\u82a8\u5c50\u8360\u696b\u8d4d\u4e69\u9e82\u7b04\u82b0\u58bc\u9e61\u525e\u6222\u866e\u4f0b\u578d\u638e\u6d0e\u8dfd\u5d74\u9c9a\u857a\u7f7d\u8e50\u59de\u6f08\u7a44\u8024\u89ed\u60ce\u5832\u5f9b\u6785\u7031\u8bd8\u9c7e\u5bb6\u52a0\u4ef7\u5047\u67b6\u7532\u4f73\u5609\u5ac1\u9a7e\u988a\u8fe6\u7a3c\u67b7\u73c8\u8888\u846d\u6d43\u80db\u75c2\u7b33\u5cac\u69da\u94be\u835a\u90cf\u94d7\u8dcf\u86f1\u605d\u659d\u9553\u7615\u6cc7\u89c1\u95f4\u5251\u4ef6\u5efa\u952e\u6e10\u7b80\u575a\u80a9\u7bad\u8230\u5c16\u76d1\u5065\u68c0\u51cf\u5978\u8270\u517c\u9274\u8d31\u6361\u526a\u6e85\u8df5\u8350\u6b7c\u62e3\u714e\u4fed\u6da7\u8327\u8c0f\u67ec\u7b3a\u7f04\u622c\u950f\u78b1\u7751\u7fe6\u996f\u8e47\u50ed\u83c5\u6bfd\u8171\u8b07\u84b9\u620b\u97af\u7b15\u9e63\u641b\u7f23\u97ac\u6e54\u88e5\u67a7\u9ca3\u8dbc\u8c2b\u8e3a\u6957\u6695\u726e\u9cd2\u7bef\u728d\u5c06\u6c5f\u8bb2\u964d\u848b\u5956\u50f5\u59dc\u7586\u5320\u6d46\u9171\u7f30\u7edb\u6868\u729f\u7ce8\u8c47\u8333\u7913\u6d1a\u8029\u8199\u9cc9\u5f36\u53eb\u6559\u4ea4\u811a\u89d2\u8f83\u5a07\u7126\u9a84\u8f7f\u6405\u72e1\u90ca\u80f6\u89c9\u56bc\u7ede\u6d47\u7f34\u86df\u6912\u4fa5\u77eb\u997a\u8549\u7901\u768e\u7a96\u8de4\u4f7c\u59e3\u9175\u9c9b\u827d\u6e6b\u91ae\u94f0\u5ce4\u832d\u5fbc\u9e6a\u656b\u564d\u50ec\u5ce7\u6ed8\u71cb\u85e0\u76a6\u65a0\u74ac\u76ad\u6054\u6f16\u721d\u63a5\u89e3\u59d0\u7ed3\u754c\u8282\u6770\u8857\u501f\u4ecb\u9636\u6d01\u6212\u7686\u52ab\u622a\u6377\u63ed\u7aed\u5c4a\u5a55\u776b\u8beb\u6840\u82a5\u6854\u9889\u55df\u5b51\u7faf\u62ee\u79f8\u73a0\u78a3\u8ba6\u75a5\u5588\u86a7\u7596\u7d5c\u6a9e\u52bc\u9ab1\u9c92\u892f\u6e5d\u8710\u5bc1\u5c8a\u6088\u8fdb\u4eca\u91d1\u7d27\u8fd1\u5c3d\u4ec5\u7981\u52b2\u9526\u5dfe\u7b4b\u6d25\u664b\u65a4\u8c28\u6d78\u895f\u747e\u70ec\u9773\u5664\u89d0\u5997\u7f19\u5807\u69ff\u887f\u8369\u9991\u537a\u7468\u5ed1\u740e\u8d46\u6e8d\u7972\u6d55\u5890\u6ba3\u73d2\u7ecf\u60ca\u7adf\u9759\u7cbe\u775b\u8b66\u4eac\u5883\u666f\u656c\u955c\u6676\u51c0\u5f84\u7ade\u4e95\u9756\u8346\u83c1\u9631\u5162\u61ac\u5a67\u9cb8\u830e\u65cc\u75c9\u6cfe\u8ff3\u749f\u80eb\u5106\u734d\u522d\u8148\u80bc\u7304\u501e\u74a5\u9e96\u9f31\u6c6b\u7aeb\u56e7\u70af\u7a98\u8fe5\u988e\u6243\u518f\u5770\u6cc2\u5c31\u4e5d\u9152\u4e45\u65e7\u6551\u7a76\u8205\u7ea0\u759a\u63ea\u548e\u9e6b\u9e20\u557e\u81fc\u7078\u8d73\u53a9\u67e9\u7396\u97ed\u9604\u50e6\u9b0f\u6855\u5de8\u4e3e\u5c45\u5c40\u5177\u636e\u805a\u5267\u8ddd\u60e7\u62d2\u4ff1\u77e9\u83ca\u62d8\u6cae\u97a0\u72d9\u6a58\u9a79\u98d3\u952f\u5480\u8e1e\u70ac\u63ac\u907d\u5028\u96ce\u949c\u8e3d\u88fe\u741a\u75bd\u8392\u8eca\u9f83\u82e3\u6989\u8bb5\u82f4\u97ab\u7117\u6910\u9514\u7b65\u5c66\u7aad\u91b5\u849f\u728b\u6fbd\u5a35\u79ec\u5d0c\u5ca0\u7820\u8152\u5f06\u6cc3\u5ca8\u5377\u5a1f\u5026\u6350\u7737\u7ee2\u9e43\u6d93\u96bd\u954c\u8832\u72f7\u9104\u9529\u684a\u7106\u7edd\u51b3\u7235\u8bc0\u6398\u53a5\u5014\u6485\u73cf\u5d1b\u6289\u5658\u652b\u8c32\u7357\u8e76\u5095\u8568\u77cd\u6a5b\u9562\u73a6\u5b53\u6877\u89d6\u5282\u7383\u7804\u5747\u541b\u519b\u4fca\u90e1\u5cfb\u94a7\u9a8f\u83cc\u7ae3\u6d5a\u73fa\u9e87\u76b2\u710c\u8470\u6343\u756f\u8399\u6659\u9caa",
    "K": "\u4f67\u5800\u5496\u625b\u532e\u54b3\u542d\u6e83\u69db\u6977\u5361\u5580\u5494\u80e9\u5f00\u51ef\u6168\u94e0\u607a\u63e9\u9534\u5ffe\u95ff\u5240\u57b2\u950e\u708c\u8488\u770b\u582a\u780d\u520a\u4f83\u574e\u52d8\u961a\u77b0\u9f9b\u6221\u5d01\u83b0\u884e\u78e1\u5d41\u5888\u6297\u5eb7\u4ea2\u7095\u6177\u7ce0\u4f09\u94aa\u95f6\u9760\u8003\u70e4\u94d0\u62f7\u7292\u5c3b\u6832\u6d18\u53ef\u523b\u514b\u5ba2\u79d1\u8bfe\u9897\u6e34\u67ef\u68f5\u58f3\u6c2a\u78d5\u55d1\u73c2\u82db\u8f72\u778c\u5777\u606a\u874c\u988f\u7aa0\u7a1e\u6e98\u75b4\u5ca2\u951e\u9ac1\u9a92\u7f02\u7241\u533c\u70a3\u524b\u80af\u6073\u5543\u57a6\u88c9\u5751\u94ff\u7841\u7a7a\u6050\u63a7\u5b54\u5d06\u7b9c\u5025\u787f\u57ea\u53e3\u6263\u5bc7\u53e9\u62a0\u853b\u82a4\u7b58\u770d\u82e6\u54ed\u9177\u5e93\u88e4\u67af\u9ab7\u7a9f\u7ed4\u55be\u5233\u77fb\u5710\u5938\u8de8\u57ae\u80ef\u630e\u4f89\u59f1\u5feb\u5757\u7b77\u84af\u54d9\u4fa9\u810d\u72ef\u90d0\u9c99\u5bbd\u6b3e\u9acb\u51b5\u72c2\u77ff\u65f7\u7736\u6846\u5321\u7b50\u54d0\u909d\u8bf3\u8bd3\u5739\u7ea9\u8d36\u593c\u6d2d\u4e8f\u6127\u76d4\u9b41\u7aa5\u594e\u8475\u5080\u777d\u9988\u9035\u9997\u559f\u5914\u7bd1\u5cbf\u63c6\u8069\u8dec\u6126\u8770\u668c\u8489\u609d\u6ac6\u9a99\u55b9\u7143\u6223\u56f0\u6606\u5764\u6346\u9cb2\u7428\u951f\u9ae1\u9603\u6083\u5803\u711c\u58f8\u9e4d\u88c8\u918c\u5a6b\u62ec\u6269\u9614\u5ed3\u86de",
    "L": "\u83c8\u7eb6\u9753\u5566\u62c9\u8fa3\u5783\u814a\u5587\u8721\u843d\u524c\u908b\u65ef\u760c\u782c\u9574\u8772\u97a1\u6765\u83b1\u8d56\u7c41\u7750\u765e\u6fd1\u5f95\u5d03\u6d9e\u8d49\u4feb\u94fc\u68be\u84dd\u70c2\u61d2\u62e6\u7bee\u5c9a\u5170\u680f\u89c8\u6f9c\u63fd\u6ee5\u5a6a\u9611\u6984\u6593\u7f06\u8934\u8c30\u7f71\u8955\u9567\u6f24\u72fc\u6d6a\u90ce\u6717\u5eca\u8782\u7405\u5577\u6994\u9512\u9606\u70fa\u8497\u83a8\u7a02\u5871\u5d00\u57cc\u6879\u7b64\u84e2\u8001\u52b3\u7262\u59e5\u635e\u5520\u4f6c\u70d9\u916a\u6d9d\u5d02\u5aea\u75e8\u91aa\u6833\u94d1\u8022\u8356\u94f9\u6f66\u7edc\u4e86\u4e50\u52d2\u53fb\u6cd0\u9cd3\u4ec2\u7c15\u561e\u808b\u96f7\u7c7b\u6cea\u7d2f\u857e\u78ca\u5792\u64c2\u5121\u956d\u7fb8\u6a91\u8012\u8bd4\u5ad8\u9179\u7f27\u790c\u7f4d\u85df\u7657\u51b7\u6123\u695e\u68f1\u5844\u5d1a\u580e\u91cc\u529b\u7406\u674e\u7acb\u79bb\u5229\u68a8\u4e3d\u5386\u793c\u5389\u4f8b\u8389\u9ece\u7483\u52b1\u54e9\u72f8\u7c92\u96b6\u540f\u6817\u6f13\u96f3\u5398\u4fd0\u7b20\u6ca5\u7bf1\u623e\u9ca4\u7281\u783e\u8354\u783a\u90e6\u85dc\u9a8a\u4fea\u9e42\u8821\u680e\u9502\u5533\u55b1\u7f79\u75e2\u8385\u4fda\u9026\u5456\u86ce\u7301\u6fa7\u91b4\u5a0c\u84e0\u8a48\u9ee7\u870a\u7f21\u5088\u67a5\u6ea7\u575c\u75a0\u7c9d\u5ae0\u7be5\u8f79\u9ca1\u75ac\u82c8\u6d6c\u8dde\u6d70\u9ce2\u91a8\u51d3\u6738\u73d5\u4fe9\u8fde\u8138\u8054\u7ec3\u604b\u601c\u70bc\u83b2\u94fe\u5e18\u5ec9\u655b\u6d9f\u9570\u740f\u6fc2\u6f4b\u6b93\u5941\u88e2\u695d\u88e3\u9ca2\u68bf\u880a\u8539\u7453\u78cf\u4e24\u91cf\u4eae\u826f\u51c9\u6881\u8f86\u7cae\u8c05\u8e09\u667e\u7cb1\u9b49\u690b\u8f8c\u589a\u60a2\u4fcd\u804a\u6599\u7597\u8fbd\u5ed6\u64a9\u5be5\u50da\u7f2d\u71ce\u6482\u7360\u9563\u5639\u77ad\u5bee\u84fc\u5c25\u9e69\u5afd\u9ace\u948c\u8e7d\u6f3b\u61ad\u7c1d\u6a51\u5217\u88c2\u730e\u54a7\u70c8\u52a3\u51bd\u8d94\u6d0c\u9b23\u6369\u57d2\u8e90\u5cdb\u811f\u6797\u4e34\u7433\u6dcb\u90bb\u9e9f\u51db\u62ce\u9716\u9cde\u541d\u8e8f\u7cbc\u78f7\u5d99\u853a\u8d41\u61d4\u8f9a\u9074\u5eea\u6f7e\u6aa9\u7498\u5549\u77b5\u81a6\u7b96\u7ff7\u4ee4\u7075\u9886\u53e6\u51cc\u73b2\u96f6\u9f84\u94c3\u9675\u5cad\u83f1\u4f36\u8046\u7fce\u7eeb\u7f9a\u5464\u82d3\u6ce0\u68c2\u74f4\u9143\u56f9\u9cae\u86c9\u9e30\u67c3\u8232\u6faa\u6624\u797e\u577d\u59c8\u6d41\u5218\u7559\u516d\u67f3\u6e9c\u7409\u69b4\u6d4f\u7624\u786b\u905b\u9646\u7efa\u938f\u998f\u9a9d\u954f\u65d2\u9560\u950d\u7198\u9e68\u98d7\u746c\u73cb\u7f76\u9e60\u7581\u788c\u9f99\u9686\u7b3c\u62e2\u80e7\u73d1\u5499\u804b\u5784\u7abf\u9647\u6cf7\u830f\u772c\u680a\u783b\u54e2\u663d\u7643\u6f0b\u697c\u6402\u6f0f\u9ac5\u9732\u964b\u55bd\u5a04\u7bd3\u9542\u507b\u877c\u8027\u848c\u7618\u5d5d\u6e87\u5245\u8def\u9c81\u5f55\u64b8\u5362\u9e7f\u7089\u82a6\u7984\u864f\u7490\u565c\u622e\u9885\u5e90\u6f09\u63b3\u8f98\u8d42\u9e93\u5364\u9e6d\u6cf8\u6f5e\u6a79\u8f82\u7b93\u80ea\u9c88\u8f73\u5786\u6e0c\u902f\u9e2c\u752a\u8557\u823b\u680c\u7c0f\u83c9\u6c07\u50c7\u742d\u9565\u52e0\u7a11\u6f9b\u7eff\u4e71\u5375\u9e3e\u5ce6\u631b\u92ae\u5b6a\u683e\u6ee6\u8114\u5a08\u8bba\u4f26\u8f6e\u4ed1\u6ca6\u62a1\u56f5\u7f57\u6d1b\u88f8\u903b\u9a86\u841d\u87ba\u9523\u5570\u73de\u9aa1\u645e\u96d2\u8366\u7ba9\u6924\u7321\u8803\u8136\u6f2f\u502e\u634b\u7630\u6cfa\u84cf\u5f8b\u7387\u65c5\u5415\u7f15\u4fa3\u9a74\u5c61\u5c65\u6ee4\u8651\u891b\u94dd\u95fe\u6988\u6c2f\u8182\u7a06\u844e\u578f\u68a0\u7565\u63a0\u950a\u5719",
    "M": "\u8122\u6fdb\u84be\u9ebf\u9702\u6ccc\u79d8\u5417\u9a6c\u5988\u9ebb\u561b\u9a82\u7801\u739b\u62b9\u8682\u87c6\u72b8\u6769\u5b56\u7943\u6469\u4e48\u4e70\u5356\u57cb\u8109\u9ea6\u8fc8\u973e\u52a2\u551b\u836c\u9fcf\u6ee1\u6162\u6f2b\u66fc\u86ee\u7792\u8513\u9992\u5e54\u8c29\u9cd7\u7f26\u5ada\u5881\u989f\u87a8\u9794\u9558\u9b18\u5fd9\u8292\u832b\u6c13\u83bd\u76f2\u87d2\u9099\u6f2d\u7264\u786d\u5c28\u727b\u5396\u6767\u6bdb\u5192\u8c8c\u732b\u77db\u5e3d\u8d38\u8302\u8305\u5187\u9ae6\u536f\u951a\u88a4\u7441\u61cb\u7266\u94c6\u6634\u8004\u87ca\u5cc1\u65c4\u6959\u6cd6\u7780\u8306\u8765\u82bc\u770a\u911a\u6ca1\u7f8e\u6bcf\u59b9\u7709\u6885\u5a9a\u9b45\u73ab\u679a\u5a92\u9709\u6627\u7164\u5bd0\u5d4b\u8393\u6e44\u8882\u6963\u9176\u9541\u90ff\u6d7c\u9e5b\u9545\u6e3c\u5a84\u7442\u7cdc\u4eec\u95e8\u95f7\u61d1\u626a\u7116\u9494\u5447\u68a6\u731b\u8499\u5b5f\u76df\u6726\u840c\u61f5\u6aac\u8722\u52d0\u867b\u8268\u9530\u5e6a\u824b\u8813\u77a2\u750d\u7374\u791e\u9e72\u5bc6\u7c73\u8ff7\u5f25\u871c\u772f\u54aa\u8c1c\u89c5\u9761\u8c27\u7962\u8288\u9e8b\u5f2d\u6c68\u7315\u5e42\u7e3b\u863c\u919a\u7955\u6549\u5627\u84c2\u8112\u6d23\u91be\u9762\u514d\u52c9\u7ef5\u7720\u68c9\u7f05\u5195\u817c\u5a29\u6e4e\u6c94\u6e11\u7704\u4e0f\u52d4\u6110\u506d\u5999\u79d2\u63cf\u82d7\u5e99\u6e3a\u7784\u6dfc\u55b5\u7f08\u85d0\u9088\u7707\u676a\u9e4b\u7f2a\u706d\u8511\u4e5c\u54a9\u7bfe\u6c11\u654f\u62bf\u60af\u95f5\u73c9\u6cef\u95fd\u76bf\u5cb7\u65fb\u7f17\u610d\u6e63\u9efe\u5fde\u9cd8\u82e0\u660e\u540d\u547d\u9e23\u51a5\u94ed\u8317\u7791\u6e9f\u9169\u669d\u879f\u6d3a\u8c2c\u9b54\u83ab\u9ed8\u6a21\u6478\u78e8\u672b\u6f20\u58a8\u964c\u5bde\u84e6\u6cab\u819c\u8309\u5b37\u8611\u6479\u998d\u8c1f\u5aeb\u79e3\u6b81\u8c8a\u977a\u8c98\u9546\u9ebd\u763c\u85e6\u8031\u67d0\u8c0b\u7738\u725f\u54de\u936a\u4f94\u86d1\u76ee\u6bcd\u6728\u6155\u5e55\u59c6\u7a46\u7267\u5893\u6c90\u66ae\u62c7\u7261\u4ea9\u52df\u7766\u82dc\u94bc\u6bea\u4eeb\u5452",
    "N": "\u9fed\u5b22\u82f6\u4f74\u5f04\u90a3\u54ea\u62ff\u5a1c\u7eb3\u5450\u637a\u8872\u94a0\u80ad\u954e\u4e78\u5357\u5976\u5948\u8010\u4e43\u9f10\u6c16\u8418\u827f\u67f0\u8ffa\u96be\u7537\u5583\u6960\u8169\u56e1\u8d67\u877b\u8433\u5a7b\u56ca\u56d4\u9995\u652e\u66e9\u9f49\u8111\u95f9\u607c\u6320\u7459\u5b6c\u5476\u6dd6\u7331\u94d9\u57b4\u86f2\u7847\u81d1\u5cf1\u5462\u8bb7\u5185\u9981\u5ae9\u6041\u80fd\u4f60\u5c3c\u6ce5\u9006\u62df\u817b\u502a\u9713\u533f\u59ae\u6eba\u6635\u7768\u65ce\u6029\u730a\u9cb5\u4f32\u576d\u94cc\u9e91\u85bf\u5e74\u5ff5\u9ecf\u62c8\u637b\u78be\u64b5\u852b\u5eff\u8f87\u9c87\u9cb6\u57dd\u5a18\u917f\u9e1f\u5c3f\u8885\u8311\u8132\u634f\u8042\u5b7d\u6d85\u8e51\u55eb\u556e\u81ec\u954a\u954d\u8616\u989e\u7cf5\u9667\u5d72\u83cd\u60a8\u5b81\u51dd\u72de\u62e7\u67e0\u549b\u6cde\u4f5e\u752f\u82e7\u804d\u725b\u626d\u7ebd\u599e\u94ae\u5ff8\u72c3\u519c\u6d53\u54dd\u4fac\u8113\u79fe\u8028\u6012\u52aa\u5974\u5f29\u9a7d\u5b65\u5089\u80ec\u782e\u7b2f\u6696\u8bfa\u632a\u61e6\u558f\u7cef\u50a9\u6426\u9518\u5973\u9495\u6067\u8844\u8650\u759f",
    "O": "\u54e6\u5662\u6b27\u5076\u5455\u6bb4\u9e25\u85d5\u6004\u74ef\u8bb4\u6ca4\u8026",
    "P": "\u73ee\u6980\u70ae\u7011\u5c4f\u6872\u6015\u722c\u5e15\u556a\u8db4\u7436\u8469\u6777\u7b62\u6f56\u8225\u6d3e\u6392\u62cd\u724c\u5f98\u6e43\u4ff3\u54cc\u7c30\u848e\u8feb\u76d8\u5224\u53db\u76fc\u6f58\u6500\u7554\u8e52\u78d0\u87e0\u69c3\u723f\u6cee\u88a2\u78fb\u897b\u80d6\u65c1\u5e9e\u5f77\u4e53\u8783\u6ec2\u9004\u96f1\u802a\u9cd1\u8dd1\u6ce1\u629b\u888d\u5486\u5e96\u72cd\u75b1\u530f\u812c\u966a\u914d\u4f69\u57f9\u8d54\u88f4\u6c9b\u5478\u80da\u5e14\u8f94\u9708\u65c6\u9185\u952b\u8843\u55b7\u76c6\u6e53\u78b0\u670b\u9e4f\u6367\u7830\u84ec\u7bf7\u5f6d\u68da\u81a8\u6f8e\u6026\u562d\u70f9\u62a8\u8283\u787c\u87db\u580b\u692a\u5f38\u6ddc\u76ae\u6279\u5c41\u75b2\u5339\u5288\u62ab\u813e\u5564\u50fb\u9739\u75de\u8b6c\u567c\u7435\u7656\u5ab2\u4e15\u6bd7\u576f\u7eb0\u7765\u90b3\u7812\u8c94\u6787\u7f74\u572e\u9f19\u868d\u94cd\u90eb\u4ef3\u4f3e\u8731\u57e4\u56ad\u9c8f\u9674\u6de0\u7513\u72c9\u6fbc\u82c9\u7247\u504f\u9a97\u7bc7\u7fe9\u9a88\u8e41\u8c1d\u80fc\u728f\u6969\u98d8\u6f02\u7968\u779f\u5ad6\u74e2\u7f25\u527d\u6734\u6b8d\u560c\u87b5\u85b8\u8508\u6487\u77a5\u82e4\u6c15\u54c1\u62fc\u8d2b\u9891\u8058\u5ad4\u98a6\u59d8\u725d\u73ad\u5e73\u51ed\u8bc4\u74f6\u840d\u82f9\u576a\u4e52\u5a09\u67b0\u9c86\u4fdc\u6cd9\u6d34\u5e21\u8353\u6d84\u73b6\u86b2\u7834\u5a46\u9887\u5761\u9b44\u6cfc\u73c0\u53f5\u9131\u7c95\u7b38\u76a4\u948b\u94b7\u9166\u5256\u6294\u88d2\u638a\u666e\u6251\u94fa\u4ec6\u8c31\u8461\u83e9\u5657\u6d66\u84b2\u6fee\u749e\u5703\u6ea5\u530d\u8386\u8e7c\u6c06\u6f7d\u917a\u9568\u9564\u84b1\u58a3\u7a59",
    "Q": "\u8793\u537b\u5947\u5176\u671f\u9f50\u8304\u6d45\u976c\u5f3a\u4e14\u8d84\u5708\u533a\u8d77\u6c14\u4e03\u5668\u9a91\u5f03\u59bb\u4f01\u542f\u65d7\u6b3a\u5c82\u6c7d\u68cb\u742a\u6ce3\u51c4\u6f06\u621a\u5951\u4e5e\u7948\u9e92\u6b67\u7426\u7941\u7eee\u6816\u7081\u6dc7\u5d0e\u780c\u8e4a\u797a\u8fc4\u675e\u5c90\u8110\u9880\u6c8f\u8dc2\u61a9\u840b\u5601\u8006\u8291\u871e\u8bab\u7947\u9ccd\u4e93\u847a\u67d2\u7da6\u8572\u7566\u82aa\u573b\u8401\u9a90\u6b39\u789b\u6c54\u951c\u69ed\u86f4\u5c7a\u7398\u6864\u57fc\u68e8\u90ea\u78dc\u9caf\u612d\u78b6\u5a4d\u6d13\u6070\u6390\u6d3d\u9ac2\u62e4\u845c\u88b7\u524d\u94b1\u5343\u6f5c\u7275\u5029\u7b7e\u6b49\u6b20\u4e7e\u8c26\u8fc1\u9063\u831c\u828a\u5d4c\u8654\u94c5\u8c34\u94b3\u9ed4\u5811\u9a9e\u4f65\u4edf\u7f31\u9621\u948e\u94a4\u63ae\u82a1\u8368\u6266\u6106\u60ad\u6434\u614a\u8930\u6c67\u80b7\u84a8\u6920\u6744\u9e50\u5c8d\u4f23\u5732\u5898\u67aa\u5899\u62a2\u8154\u545b\u8dc4\u8537\u9535\u7f8c\u6215\u6217\u8941\u5af1\u6a2f\u956a\u709d\u7f9f\u8723\u73b1\u9516\u8503\u5de7\u6084\u77a7\u6572\u6865\u4e54\u4fcf\u7fd8\u7a8d\u9798\u6194\u5ced\u8df7\u4fa8\u6a35\u64ac\u9539\u8c2f\u6a47\u8bee\u835e\u6100\u5281\u7857\u9792\u785a\u7f32\u96c0\u5207\u7a83\u602f\u59be\u60ec\u9532\u6308\u7ba7\u90c4\u4eb2\u79e6\u7434\u4fb5\u52e4\u5bdd\u64d2\u94a6\u82b9\u6c81\u79bd\u8983\u5659\u887e\u63ff\u82a9\u6eb1\u5423\u55ea\u9513\u6a8e\u9a8e\u616c\u5d5a\u8bf7\u8f7b\u6e05\u9752\u60c5\u5e86\u6674\u503e\u537f\u64ce\u9877\u873b\u7b90\u6c22\u7f44\u78ec\u7dae\u6c30\u9ee5\u6aa0\u9cad\u82d8\u570a\u7883\u5ebc\u52cd\u7a77\u743c\u7a79\u8315\u909b\u7b47\u86e9\u928e\u6c42\u7403\u79cb\u4e18\u90b1\u56da\u88d8\u914b\u866c\u7cd7\u9cc5\u86af\u4fc5\u6cc5\u9052\u9011\u6978\u72b0\u8429\u8764\u7486\u5def\u8d47\u9e59\u97a7\u9f3d\u8a04\u53bb\u53d6\u8da3\u66f2\u5c48\u8eaf\u9a71\u5a36\u8d8b\u6e20\u89d1\u77bf\u5c96\u86d0\u86c6\u8862\u795b\u9ee2\u766f\u9612\u9f8b\u8556\u8627\u6710\u74a9\u52ac\u78f2\u8bce\u883c\u88aa\u6c0d\u9e32\u9eb9\u80e0\u7048\u9f29\u7ad8\u5765\u5168\u6743\u62f3\u529d\u6cc9\u72ac\u5238\u8737\u75ca\u8be0\u8343\u98a7\u7efb\u94e8\u7b4c\u9b08\u919b\u609b\u4f7a\u754e\u68ec\u9cc8\u8f81\u5a58\u7454\u5374\u786e\u7f3a\u7638\u9e4a\u9619\u9615\u69b7\u7094\u60ab\u788f\u57c6\u7fa4\u88d9\u9021\u56f7",
    "R": "\u633c\u670a\u5827\u7136\u67d3\u71c3\u5189\u9aef\u82d2\u86ba\u8ba9\u56b7\u58e4\u6518\u74e4\u79b3\u7a70\u703c\u8618\u5134\u7ed5\u6270\u9976\u5a06\u6861\u835b\u70ed\u60f9\u4eba\u4efb\u8ba4\u5fcd\u4ec1\u5203\u97e7\u58ec\u996a\u4ede\u7eab\u7a14\u834f\u598a\u887d\u8f6b\u7eb4\u8bb1\u4ecd\u6254\u65e5\u9a72\u5bb9\u8363\u878d\u84c9\u7ed2\u6eb6\u620e\u6995\u8338\u7194\u5197\u5d58\u9555\u877e\u72e8\u7462\u8089\u67d4\u63c9\u8e42\u7cc5\u97a3\u5982\u5165\u8fb1\u4e73\u5112\u8339\u6c5d\u8815\u5b7a\u8925\u5685\u6fe1\u7f1b\u8966\u6ebd\u84d0\u6d33\u85b7\u98a5\u5b2c\u94f7\u8f6f\u962e\u74c0\u5a86\u745e\u9510\u854a\u777f\u82ae\u868b\u8564\u6798\u6c6d\u6da6\u95f0\u82e5\u5f31\u504c\u7bac\u5a7c\u7207\u84bb\u9100",
    "S": "\u8fbb\u4e96\u55c4\u5239\u88f3\u6c88\u665f\u5319\u8870\u77f3\u81bb\u9002\u4fdf\u845a\u6492\u6d12\u98d2\u4ee8\u8428\u5345\u9778\u6332\u6f75\u810e\u8d5b\u585e\u816e\u567b\u9cc3\u4e09\u6563\u4f1e\u53c1\u9993\u6bf5\u7cc1\u4e27\u6851\u55d3\u6421\u98a1\u78c9\u626b\u9a9a\u5ac2\u6414\u81ca\u7619\u7f2b\u57fd\u6e9e\u8272\u745f\u6da9\u556c\u7a51\u94ef\u74b1\u68ee\u50e7\u5565\u50bb\u6740\u838e\u715e\u7eb1\u6c99\u53a6\u970e\u7802\u9ca8\u88df\u94e9\u6b43\u75e7\u553c\u6749\u6652\u7b5b\u917e\u5c71\u5220\u95ea\u5584\u6247\u886b\u73ca\u64c5\u59d7\u8baa\u9655\u717d\u81b3\u8dda\u6f78\u7f2e\u6c55\u8d61\u9cdd\u8222\u82eb\u5b17\u912f\u9a9f\u87ee\u58a1\u5261\u759d\u829f\u57cf\u9490\u5da6\u6671\u70fb\u4e0a\u4f24\u5546\u5c1a\u8d4f\u664c\u6b87\u89de\u71b5\u5892\u7ef1\u57a7\u5c11\u70e7\u7a0d\u7ecd\u54e8\u90b5\u52fa\u68a2\u97f6\u52ad\u634e\u828d\u82d5\u8244\u7b72\u6f72\u86f8\u7744\u67d6\u73bf\u5c04\u8bbe\u820d\u86c7\u820c\u6d89\u6444\u793e\u5962\u6151\u8d66\u4f58\u9e9d\u8d4a\u7572\u731e\u6b59\u6ee0\u538d\u62fe\u8c01\u795e\u6df1\u8eab\u751a\u4ec0\u4f38\u5ba1\u7533\u614e\u547b\u6e17\u5a76\u7ec5\u80be\u8398\u73c5\u8703\u54c2\u5a20\u71ca\u7606\u6939\u7837\u8bdc\u7521\u8c02\u77e7\u80c2\u4f81\u77ab\u9cb9\u5c7e\u751f\u58f0\u5723\u80dc\u5347\u7701\u5269\u7ef3\u7272\u7b19\u7525\u6607\u5d4a\u771a\u965e\u662f\u65f6\u4e8b\u5b9e\u5341\u5e08\u4f7f\u5c4e\u4e16\u59cb\u5931\u58eb\u6e7f\u8bc6\u89c6\u52bf\u5e02\u5ba4\u5f0f\u793a\u8bd5\u53f2\u98df\u65bd\u91ca\u8bd7\u5c38\u6c0f\u4f8d\u9970\u8a93\u9a76\u901d\u72ee\u566c\u4ed5\u77e2\u62ed\u55dc\u4f3c\u8680\u6043\u67ff\u5f11\u8f7c\u8671\u8c25\u8210\u5a9e\u8c55\u83b3\u7b6e\u84cd\u87ab\u70bb\u9ca5\u596d\u6e5c\u57d8\u794f\u683b\u8d33\u94c8\u9cba\u9f2b\u90bf\u9e24\u6d49\u896b\u624b\u53d7\u6536\u9996\u5b88\u719f\u517d\u6388\u7626\u552e\u5bff\u72e9\u7ef6\u824f\u4e66\u6570\u672f\u6811\u5c5e\u53d4\u675f\u8212\u8f93\u8ff0\u6b8a\u9f20\u758f\u6dd1\u7ad6\u7f72\u5885\u68b3\u8700\u6055\u500f\u6691\u5eb6\u6f31\u8d4e\u59dd\u67a2\u852c\u85af\u66d9\u6292\u5b70\u620d\u587e\u7ebe\u6f8d\u9ecd\u6cad\u79eb\u6bb3\u83fd\u8167\u6bf9\u6445\u5a4c\u9103\u964e\u9683\u5237\u800d\u5530\u5e05\u6454\u7529\u87c0\u6813\u62f4\u6dae\u95e9\u8168\u53cc\u723d\u971c\u5b40\u9e74\u9aa6\u7935\u6c34\u7761\u7a0e\u5e28\u8bf4\u987a\u77ac\u542e\u821c\u70c1\u7855\u6714\u94c4\u69ca\u6420\u5981\u84b4\u6b7b\u56db\u601d\u65af\u53f8\u4e1d\u79c1\u5bfa\u6495\u8086\u5636\u53ae\u7940\u55e3\u9972\u5df3\u6cd7\u549d\u59d2\u6c5c\u9a77\u9e36\u5155\u6d98\u7f0c\u86f3\u6f8c\u9536\u7b25\u801c\u98d4\u51d8\u8652\u6952\u9001\u677e\u5b8b\u8038\u8bf5\u6002\u9882\u5d69\u609a\u8bbc\u5fea\u6dde\u5d27\u7ae6\u51c7\u83d8\u5a00\u641c\u8258\u55fd\u55d6\u53df\u98d5\u64de\u998a\u85ae\u6eb2\u55fe\u953c\u5ecb\u778d\u8490\u878b\u8bc9\u901f\u82cf\u7d20\u5bbf\u4fd7\u8083\u5851\u9165\u7c0c\u7c9f\u7a23\u6eaf\u612b\u5919\u8c21\u7aa3\u850c\u6d91\u55c9\u50f3\u89eb\u9a95\u7526\u9e54\u5083\u8e5c\u7f29\u7b97\u9178\u849c\u72fb\u867d\u968f\u5c81\u788e\u9042\u968b\u9ad3\u795f\u7a57\u9083\u96a7\u7ee5\u71e7\u7762\u772d\u837d\u8c07\u6fc9\u7a5f\u74b2\u895a\u65de\u5b59\u635f\u7b0b\u96bc\u836a\u72f2\u69ab\u98e7\u6240\u7d22\u9501\u68ad\u7410\u55cd\u5506\u5a11\u55e6\u84d1\u686b\u5522\u7743\u7fa7\u6eb9",
    "T": "\u7260\u6039\u8599\u7551\u9fec\u6a0b\u51c3\u6c3d\u5018\u6a18\u7118\u63d0\u56e4\u9a6e\u67c1\u6c64\u4ed6\u5979\u5b83\u5854\u8e0f\u62d3\u584c\u69bb\u8e4b\u9062\u631e\u8dbf\u736d\u7942\u95fc\u9cce\u94ca\u6ebb\u9618\u891f\u97b3\u592a\u53f0\u6001\u62ac\u6cf0\u80ce\u6c70\u82d4\u8dc6\u949b\u85b9\u80bd\u915e\u90b0\u70b1\u9c90\u8c08\u53f9\u63a2\u5766\u8d2a\u575b\u644a\u6ee9\u8c2d\u6f6d\u762b\u6bef\u70ad\u5fd0\u6a80\u75f0\u78b3\u8892\u6619\u574d\u90ef\u5013\u952c\u94bd\u74ae\u60d4\u83fc\u6983\u78f9\u8eba\u7cd6\u8d9f\u70eb\u5802\u5510\u819b\u6dcc\u68e0\u5858\u642a\u87b3\u50a5\u746d\u9557\u5e11\u8e5a\u5621\u6e8f\u8797\u7fb0\u954b\u8025\u57eb\u94f4\u910c\u5957\u9003\u8ba8\u6843\u6d9b\u638f\u9676\u6ed4\u8404\u6dd8\u97ec\u5555\u9955\u7ee6\u6d2e\u68bc\u7ef9\u5f22\u9f17\u6146\u7279\u5fd1\u615d\u94fd\u5fd2\u75bc\u817e\u85e4\u6ed5\u8a8a\u87a3\u7e22\u71a5\u9898\u4f53\u66ff\u8e22\u68af\u8e44\u60d5\u6d95\u557c\u5254\u5c49\u5243\u568f\u501c\u7f07\u9016\u8351\u918d\u608c\u9e48\u7ee8\u9511\u88fc\u8daf\u9046\u9cc0\u64ff\u7445\u5929\u7530\u751c\u6dfb\u586b\u8214\u606c\u8146\u9617\u6b84\u5fdd\u6e49\u754b\u89cd\u7471\u63ad\u76f7\u9ec7\u666a\u6cba\u6ddf\u6761\u8df3\u6311\u773a\u8fe2\u7a95\u4f7b\u7b24\u7967\u9aeb\u7c9c\u9f86\u8729\u9ca6\u6713\u5b25\u94c1\u8d34\u5e16\u992e\u841c\u542c\u505c\u5385\u633a\u5ead\u5ef7\u5a77\u4ead\u8247\u9706\u6c40\u8713\u94e4\u8476\u839b\u73fd\u6883\u70c3\u6e1f\u988b\u686f\u4fb9\u5722\u70f6\u540c\u901a\u75db\u7edf\u7ae5\u94dc\u7b52\u6876\u6345\u77b3\u6850\u4f5f\u5f64\u6078\u6f7c\u55f5\u50ee\u916e\u4edd\u833c\u66c8\u783c\u70d4\u6a66\u54c3\u7a5c\u9c96\u5cc2\u5934\u6295\u5077\u900f\u9ab0\u7a81\u56fe\u571f\u5f92\u5410\u9014\u6d82\u5c60\u5154\u79c3\u51f8\u837c\u83df\u948d\u580d\u9174\u7a0c\u816f\u8456\u688c\u56e2\u6e4d\u629f\u5f56\u7583\u732f\u7153\u63a8\u9000\u817f\u9893\u892a\u8715\u717a\u9b4b\u541e\u5c6f\u81c0\u8c5a\u9968\u66be\u9c80\u5749\u5ff3\u711e\u62d6\u8131\u6258\u59a5\u9640\u9a7c\u553e\u4f57\u692d\u5768\u6cb1\u7823\u9e35\u8dce\u9161\u6a50\u67dd\u4f82\u9f0d\u5eb9\u7ba8\u572b\u841a",
    "W": "\u63fe\u839e\u5ec6\u6da1\u9697\u739f\u4e07\u65e0\u5594\u54c7\u74e6\u5a03\u6316\u889c\u86d9\u5a32\u6d3c\u4f64\u7a8a\u817d\u576c\u7556\u5916\u6b6a\u5d34\u5b8c\u665a\u73a9\u5f2f\u7897\u6e7e\u5a49\u633d\u8155\u5b9b\u987d\u4e38\u534d\u60cb\u873f\u742c\u7ea8\u5a60\u7696\u7efe\u525c\u83c0\u8c4c\u7579\u70f7\u8118\u8284\u5846\u6900\u738b\u671b\u5f80\u5fd8\u7f51\u4ea1\u6c6a\u5984\u65fa\u6789\u60d8\u7f54\u9b4d\u5c22\u8f8b\u5c2a\u4e3a\u4f4d\u5fae\u672a\u56f4\u536b\u5a01\u5473\u7ef4\u5371\u59d4\u80c3\u4f1f\u8c13\u552f\u6170\u5c3e\u5582\u9b4f\u8587\u60df\u8fdd\u97e6\u754f\u4f2a\u5c09\u5dcd\u851a\u504e\u840e\u82c7\u709c\u73ae\u7325\u5a13\u5e37\u7eac\u6e2d\u6845\u5d6c\u732c\u8473\u75ff\u95f1\u7168\u8bff\u97ea\u9036\u5e0f\u5729\u6f4d\u6ea6\u9c94\u8249\u9688\u6d27\u6ca9\u9728\u6da0\u4eb9\u78a8\u9cc2\u9cda\u715f\u741f\u7859\u85b3\u5cd7\u6d08\u87b1\u95ee\u6587\u6e29\u95fb\u7a33\u543b\u7eb9\u96ef\u868a\u82a0\u761f\u7d0a\u6c76\u520e\u7086\u74ba\u960c\u8f92\u6985\u8570\u9cc1\u7fc1\u55e1\u74ee\u84ca\u8579\u9e5f\u6ec3\u6211\u63e1\u7a9d\u5367\u6c83\u502d\u9f8c\u8717\u6e25\u65a1\u5e44\u631d\u83b4\u786a\u809f\u5053\u6db4\u8e12\u7269\u4e94\u6b66\u52a1\u5c4b\u821e\u5434\u5348\u8bef\u96fe\u4e4c\u609f\u4f0d\u545c\u5deb\u543e\u6c61\u6342\u52ff\u5140\u4fae\u5514\u68a7\u59a9\u829c\u8bec\u575e\u6bcb\u6664\u8708\u90ac\u9e49\u620a\u5fe4\u9a9b\u9e5c\u4ef5\u5a7a\u94a8\u674c\u7110\u5e91\u5be4\u92c8\u75e6\u6003\u727e\u572c\u6d6f\u82b4\u8fd5\u9f2f\u65ff\u9770\u6d3f\u9e40\u90da\u5c7c\u73f7\u5cff\u73f8\u94fb",
    "X": "\u77fd\u96eb\u54b2\u6b3b\u54a5\u867e\u5df7\u5413\u620f\u6821\u5671\u7ea4\u620c\u5618\u6d17\u897f\u559c\u606f\u7ec6\u5e0c\u4e60\u5438\u60dc\u5e2d\u88ad\u6089\u563b\u6790\u7a00\u7199\u5915\u6670\u6eaa\u516e\u727a\u819d\u5ab3\u9699\u6614\u9521\u5b09\u7184\u7280\u66e6\u79a7\u7699\u73ba\u6c50\u8725\u595a\u550f\u7fb2\u6dc5\u5f99\u71b9\u87cb\u7fd5\u6a84\u50d6\u7ab8\u94e3\u90d7\u665e\u70ef\u5c43\u6d60\u960b\u6a28\u5092\u91af\u96b0\u8785\u7214\u5c63\u7852\u91d0\u8478\u8c68\u798a\u9969\u90e4\u89cb\u7a78\u5db2\u8204\u823e\u8c3f\u6053\u84f0\u9f37\u7c9e\u5dc7\u6199\u7ee4\u83e5\u67b2\u6f5f\u80b8\u9145\u774e\u89ff\u5d8d\u4fd9\u66bf\u71bb\u997b\u9cdb\u4e0b\u590f\u4fa0\u971e\u778e\u72ed\u6687\u5ce1\u8f96\u5323\u7455\u9050\u9ee0\u5477\u72ce\u7f45\u7856\u67d9\u53da\u7fc8\u5148\u73b0\u663e\u7ebf\u9669\u4ed9\u54b8\u9c9c\u9650\u95f2\u9677\u53bf\u732e\u8d24\u5acc\u7fa1\u5f26\u6380\u5baa\u8854\u5a34\u6d8e\u9985\u8237\u817a\u66b9\u82cb\u51bc\u85d3\u9528\u9730\u8df9\u5ffa\u75eb\u7946\u5c98\u9170\u8de3\u71f9\u72dd\u86ac\u7303\u7c7c\u9e47\u7b45\u83b6\u6c19\u6326\u5d04\u7f10\u5b45\u4f2d\u7992\u60f3\u5411\u76f8\u50cf\u8c61\u54cd\u9999\u9879\u4e61\u4eab\u7fd4\u7bb1\u7965\u8be6\u6e58\u53a2\u8944\u9576\u6a61\u9977\u9aa7\u98e8\u5ea0\u7f03\u8297\u9c9e\u74d6\u8459\u73e6\u5c0f\u7b11\u6d88\u6653\u8427\u6548\u9500\u8096\u5578\u5b5d\u900d\u6f47\u524a\u56a3\u9704\u5bb5\u54ee\u7bab\u7b71\u67ad\u785d\u9a81\u6dc6\u9b48\u7ee1\u54d3\u9e2e\u5d24\u67b5\u7307\u6d28\u7fdb\u8653\u6d8d\u87cf\u6569\u6ee7\u769b\u4e9b\u8840\u8c22\u5199\u90aa\u534f\u978b\u659c\u6cc4\u80c1\u6b47\u5c51\u68b0\u643a\u8c10\u5378\u631f\u6cfb\u61c8\u874e\u87f9\u4eb5\u9082\u5055\u69ad\u71ee\u6954\u64b7\u7023\u736c\u52f0\u5ee8\u7f2c\u8e9e\u7ec1\u6e2b\u85a4\u698d\u63f3\u6fa5\u85a2\u5070\u65b0\u5fc3\u4fe1\u6b23\u8f9b\u99a8\u85aa\u6b46\u6615\u8845\u82af\u946b\u5ffb\u950c\u7098\u56df\u4f08\u6027\u661f\u5f62\u5174\u9192\u5e78\u578b\u59d3\u5211\u8165\u674f\u7329\u60fa\u90a2\u60bb\u8365\u64e4\u9649\u8347\u9967\u9a8d\u784e\u9498\u7446\u5a5e\u94cf\u714b\u5144\u80f8\u96c4\u51f6\u718a\u6c79\u5308\u828e\u8bbb\u5910\u8bc7\u4fee\u79c0\u4f11\u7f9e\u8896\u7ee3\u55c5\u673d\u9508\u54bb\u5cab\u8c85\u9990\u5ea5\u8129\u6eb4\u7407\u9af9\u9e3a\u73db\u6eeb\u8bb8\u7eed\u9700\u987b\u865a\u5f90\u7eea\u5e8f\u65ed\u53d9\u5401\u84c4\u7d6e\u5a7f\u6064\u6829\u589f\u8be9\u7166\u80e5\u9157\u987c\u52d6\u84ff\u76f1\u9b46\u6d2b\u6e86\u7cc8\u8c1e\u5aad\u662b\u9191\u73dd\u65f4\u6e51\u5194\u57bf\u9009\u7384\u5ba3\u65cb\u8f69\u60ac\u55a7\u7487\u7729\u70ab\u8431\u6f29\u7eda\u6684\u6e32\u714a\u6ceb\u94c9\u7444\u70dc\u7663\u79a4\u8c16\u5107\u73b9\u6966\u78b9\u6645\u8852\u7ffe\u75c3\u6621\u54ba\u6103\u66b6\u7404\u5b66\u96ea\u7a74\u859b\u9774\u8c11\u8e05\u9cd5\u8313\u5cc3\u5bfb\u8bad\u8fc5\u5de1\u8baf\u8be2\u900a\u5faa\u52cb\u718f\u65ec\u9a6f\u8340\u85b0\u6b89\u91ba\u6d35\u5ccb\u5dfd\u73e3\u6c5b\u5f87\u6d54\u57d9\u6042\u8548\u9c9f\u66db\u736f\u5640\u6812",
    "Y": "\u84fa\u54df\u5537\u80b2\u814c\u6d8c\u8f67\u54d5\u6f4f\u7b60\u92c6\u9f88\u756c\u4fde\u59a7\u9057\u65bc\u53f6\u7aa8\u5440\u4e9a\u538b\u96c5\u7259\u4e2b\u8bb6\u6daf\u54d1\u5d16\u5a05\u62bc\u9e2d\u9e26\u8859\u82bd\u4f22\u740a\u6860\u775a\u57ad\u5c88\u8fd3\u869c\u73a1\u63e0\u7330\u6c29\u7811\u5810\u773c\u8a00\u4e25\u70df\u6f14\u9a8c\u7814\u71d5\u989c\u63a9\u5ef6\u538c\u8273\u708e\u6cbf\u7130\u5ca9\u6df9\u54bd\u5bb4\u5ae3\u598d\u5f66\u96c1\u960e\u76d0\u7109\u884d\u6a90\u5944\u781a\u7131\u4fe8\u664f\u80ed\u8712\u9b47\u9609\u6e6e\u7430\u7b75\u5043\u95eb\u6079\u8c1a\u5156\u5830\u9122\u6edf\u8d5d\u5501\u9f39\u82ab\u90fe\u917d\u990d\u53a3\u8c33\u5d26\u5f07\u9ee1\u7f68\u6e30\u639e\u5b3f\u68ea\u624a\u6c87\u7517\u8758\u5895\u622d\u6bb7\u6f39\u8664\u89c3\u517b\u6837\u9633\u6768\u626c\u6d0b\u4ef0\u592e\u7f8a\u75d2\u6f3e\u6c27\u6059\u4f6f\u9e2f\u6b83\u600f\u79e7\u7080\u6cf1\u9785\u5f89\u70ca\u75a1\u65f8\u98cf\u7f95\u86d8\u579f\u739a\u5489\u9496\u8981\u6447\u836f\u5996\u8170\u54ac\u9065\u8000\u7476\u59da\u9080\u94a5\u592d\u8c23\u5e7a\u7a91\u5c27\u5406\u80b4\u7ea6\u66dc\u7a88\u6773\u8200\u723b\u9e5e\u5fad\u8f7a\u9cd0\u5d3e\u7a85\u5ce3\u579a\u73e7\u977f\u733a\u5ab1\u7e47\u4e5f\u4e1a\u591c\u7237\u91ce\u6db2\u8036\u9875\u66f3\u51b6\u70e8\u564e\u814b\u9765\u6930\u6396\u6654\u90ba\u8c12\u63f6\u94d8\u503b\u998c\u4e00\u4ee5\u5df2\u610f\u8863\u4ebf\u6613\u4f9d\u4e49\u5f02\u7591\u8bae\u533b\u4f0a\u79fb\u5fc6\u827a\u4ea6\u7ffc\u76ca\u5b9c\u6905\u4eea\u9038\u59e8\u6021\u6291\u6bc5\u5f79\u8bd1\u5937\u6ea2\u54a6\u501a\u77e3\u8c0a\u4e59\u8681\u5955\u6f2a\u75ab\u7ece\u88d4\u63d6\u9890\u9a7f\u5f08\u61ff\u9091\u71a0\u5c79\u6c82\u7fbf\u8be3\u7fcc\u8f76\u5453\u7fca\u8734\u5f0b\u54bf\u65d6\u794e\u81c6\u5f5d\u8d3b\u566b\u4f5a\u8fe4\u58f9\u7f22\u7ff3\u80f0\u75cd\u858f\u5db7\u9974\u82e1\u6092\u7317\u8bd2\u9edf\u5cc4\u9571\u603f\u7719\u8084\u94f1\u6339\u4e42\u5208\u7654\u9552\u57f8\u4f7e\u572f\u7617\u71da\u5293\u6baa\u6d65\u6246\u5ed9\u7c03\u5ad5\u8223\u6759\u9487\u9e62\u5ba7\u6d22\u914f\u7e44\u88db\u6938\u8e26\u6245\u4f41\u52da\u531c\u87a0\u9e5d\u678d\u6f69\u56e0\u97f3\u5f15\u9690\u94f6\u9634\u5370\u541f\u996e\u6deb\u59fb\u5c39\u8335\u763e\u80e4\u836b\u5bc5\u57a0\u6c24\u8693\u5591\u6d07\u911e\u5924\u972a\u72fa\u6114\u5819\u8a1a\u5432\u94df\u569a\u798b\u9a83\u616d\u784d\u73e2\u831a\u87eb\u9f82\u5d1f\u6eb5\u6b45\u5e94\u5f71\u82f1\u8425\u8fce\u786c\u9e70\u8d62\u6620\u83b9\u76c8\u5a74\u6a31\u9896\u83ba\u8747\u5b34\u8424\u8367\u8426\u745b\u7f28\u701b\u5624\u81ba\u6ee2\u9e66\u7f42\u748e\u90e2\u988d\u8314\u6979\u6484\u6f46\u5ab5\u763f\u9533\u84e5\u6e81\u5a96\u7528\u6c38\u62e5\u52c7\u4f63\u5eb8\u6cf3\u96cd\u548f\u752c\u6175\u4fd1\u607f\u81c3\u86f9\u9095\u8e0a\u5889\u955b\u9899\u75c8\u58c5\u9954\u9cd9\u6fad\u9118\u57c7\u9cac\u6810\u5581\u6709\u53c8\u7531\u53cb\u6e38\u53f3\u4f18\u72b9\u5e7d\u6cb9\u5c24\u5fe7\u60a0\u8bf1\u5e7c\u4f51\u90ae\u9edd\u5466\u6538\u9c7f\u9149\u67da\u7950\u94c0\u7337\u91c9\u83a0\u56ff\u9f2c\u5ba5\u839c\u75a3\u4f91\u7256\u8763\u86b4\u7f91\u86b0\u83b8\u5363\u9e80\u8030\u6d5f\u69f1\u94d5\u9c89\u4e0e\u4e8e\u8bed\u96e8\u7389\u4f59\u9047\u6b32\u7fbd\u5b87\u9c7c\u9884\u5fa1\u90c1\u8c6b\u57df\u72f1\u4e88\u6108\u6d74\u8a89\u6109\u611a\u88d5\u5a31\u745c\u55bb\u5bd3\u6e14\u865e\u79b9\u715c\u8206\u8c15\u903e\u6986\u5c7f\u94b0\u9a6d\u6e1d\u8fc2\u6de4\u6bd3\u7440\u59a4\u6631\u9685\u79ba\u828b\u807f\u81fe\u63c4\u5cea\u89ce\u59aa\u8c00\u8174\u76c2\u5f67\u5ebe\u7600\u71cf\u68eb\u872e\u5704\u7afd\u6b24\u8438\u9e6c\u9b3b\u9f89\u7ab3\u5709\u7ea1\u72f3\u4fe3\u71e0\u7610\u4f1b\u996b\u6def\u9608\u8753\u8201\u9079\u96e9\u9e46\u7aac\u71a8\u7399\u5d5b\u5809\u8915\u77de\u5d4e\u84e3\u9ac3\u6eea\u6086\u6554\u9098\u9105\u8245\u539f\u8fdc\u5458\u5143\u9662\u613f\u56ed\u6e90\u5706\u7f18\u6028\u63f4\u8881\u8f95\u6e0a\u51a4\u5a9b\u82d1\u733f\u9e33\u57a3\u9e22\u6c85\u7230\u7457\u586c\u9f0b\u63be\u57b8\u8788\u6a7c\u870e\u5ac4\u7ba2\u6e72\u7722\u7fb1\u8d8a\u6708\u8dc3\u5cb3\u60a6\u66f0\u9605\u7ca4\u73a5\u94ba\u6a3e\u5216\u5f5f\u7039\u9fa0\u721a\u7c65\u4e91\u8fd0\u6655\u5141\u97f5\u82b8\u5b55\u8574\u5300\u9668\u915d\u6120\u6c32\u8018\u6600\u7ead\u6b92\u97eb\u90d3\u8d5f\u607d\u90e7\u72c1\u6c84\u5998\u7f0a\u7174\u7b7c\u6da2\u99a7",
    "Z": "\u8fd9\u81a3\u8de9\u55b3\u6942\u91cd\u79cd\u67f7\u562c\u5e62\u690e\u5179\u5352\u6512\u9142\u7fdf\u7c98\u6805\u53ec\u6298\u5cd9\u6b96\u548b\u7838\u6742\u5482\u531d\u624e\u81dc\u62f6\u5728\u518d\u8f7d\u707e\u5bb0\u683d\u54c9\u4ed4\u5d3d\u753e\u54b1\u8d5e\u6682\u7c2a\u74d2\u933e\u7ccc\u8db1\u661d\u810f\u846c\u8d43\u81e7\u5958\u7242\u9a75\u65e9\u9020\u906d\u7cdf\u6fa1\u8e81\u71e5\u51ff\u566a\u7076\u67a3\u7682\u85fb\u86a4\u5523\u74aa\u6165\u7c09\u5219\u8d23\u62e9\u6cfd\u5567\u4ec4\u7b2e\u5e3b\u8d5c\u6603\u8234\u7ba6\u8fee\u9c97\u8d3c\u600e\u8c2e\u589e\u8d60\u618e\u9503\u7f2f\u7511\u7f7e\u77f0\u912b\u7efc\u70b8\u7728\u8bc8\u4e4d\u6e23\u672d\u95f8\u69a8\u5412\u54a4\u86b1\u94e1\u9c8a\u63f8\u781f\u54f3\u5953\u62c3\u6313\u75c4\u5284\u9705\u67de\u6ea0\u9c9d\u9f47\u6458\u5b85\u5be8\u503a\u7a84\u658b\u7635\u8c78\u7ad9\u6218\u5c55\u5360\u65a9\u6cbe\u8638\u7efd\u6808\u76cf\u8a79\u6e5b\u5d2d\u77bb\u8f97\u6be1\u65c3\u8c35\u640c\u98d0\u9e6f\u5061\u6834\u9ce3\u5f20\u7ae0\u638c\u4e08\u5e10\u4ed7\u969c\u6da8\u6756\u8d26\u748b\u80c0\u5f70\u87d1\u7634\u6a1f\u6f33\u7350\u5d82\u5e5b\u9123\u5adc\u66b2\u4ec9\u627e\u7167\u62db\u8d75\u7f69\u7740\u722a\u662d\u5146\u8bcf\u6cbc\u8087\u948a\u68f9\u7b0a\u66cc\u5541\u65d0\u8005\u54f2\u906e\u6d59\u8f99\u8f84\u8936\u86f0\u8517\u8707\u9e67\u5586\u8c2a\u8d6d\u67d8\u78d4\u9517\u556b\u6662\u8a5f\u8457\u771f\u9635\u9707\u9547\u73cd\u9488\u632f\u6715\u4fa6\u8d1e\u6795\u8bca\u7504\u5e27\u659f\u796f\u81fb\u6862\u7bb4\u7f1c\u5733\u699b\u8d48\u84c1\u799b\u75b9\u7827\u9e29\u8f78\u7a39\u6d48\u7467\u755b\u80d7\u9b12\u8897\u8474\u63d5\u6623\u7ebc\u6b63\u6574\u653f\u4e89\u8bc1\u5f81\u90d1\u7741\u6323\u6014\u75c7\u84b8\u94ee\u7b5d\u72f0\u62ef\u5ce5\u94b2\u8be4\u70dd\u53ea\u77e5\u76f4\u81f3\u4e4b\u6307\u503c\u5236\u652f\u5fd7\u6b62\u6cbb\u8d28\u7f6e\u81f4\u804c\u667a\u7eb8\u7ec7\u6267\u679d\u690d\u65e8\u829d\u5431\u80a2\u4f84\u8102\u5740\u6c41\u6ede\u7a1a\u63b7\u79e9\u7a92\u82b7\u631a\u8718\u5e1c\u7099\u8dbe\u54ab\u75e3\u5fb5\u96c9\u7957\u6800\u75d4\u6809\u7949\u684e\u86ed\u9e37\u90c5\u8e2f\u8d3d\u965f\u9a98\u5f58\u8dd6\u8f7e\u646d\u67b3\u916f\u5e19\u7994\u536e\u6c9a\u80dd\u89ef\u7d77\u57f4\u8f75\u9ef9\u8e2c\u5fee\u664a\u7564\u6ecd\u7a19\u627a\u94da\u9527\u7590\u8df1\u5ea4\u6cdc\u68bd\u69b0\u4e2d\u7ec8\u4f17\u949f\u5fe0\u4ef2\u8877\u80bf\u51a2\u8e35\u76c5\u953a\u822f\u87bd\u67ca\u833d\u5468\u5dde\u76b1\u6d32\u5492\u5b99\u821f\u9aa4\u7ca5\u8098\u8f74\u663c\u5e1a\u80c4\u7ea3\u7ec9\u8bcc\u59af\u78a1\u7c40\u914e\u8f80\u8d52\u9e3c\u836e\u5a64\u4f4f\u4e3b\u6ce8\u52a9\u6731\u73e0\u8bf8\u9010\u7af9\u732a\u795d\u7b51\u67f1\u9a7b\u5631\u70db\u716e\u86db\u682a\u94f8\u8bdb\u7afa\u77a9\u4f2b\u62c4\u4f8f\u8d2e\u8331\u6d19\u86c0\u6e1a\u7bb8\u70b7\u94e2\u8e85\u82ce\u677c\u7fe5\u69e0\u9e88\u6f74\u8233\u90be\u7ebb\u6a65\u782b\u75b0\u880b\u7603\u6293\u9afd\u62fd\u8f6c\u4e13\u8d5a\u7816\u64b0\u7bc6\u9994\u989b\u556d\u50ce\u7451\u88c5\u72b6\u5e84\u649e\u58ee\u5986\u6869\u8ffd\u5760\u7f00\u9525\u60f4\u8d58\u9a93\u7f12\u96b9\u51c6\u8c06\u80ab\u7a80\u8860\u684c\u5353\u6349\u7422\u707c\u62d9\u6d4a\u956f\u914c\u5544\u8301\u6dbf\u64e2\u65ab\u6fef\u502c\u6d5e\u8bfc\u68c1\u799a\u6913\u666b\u53d5\u6c4b\u5b50\u81ea\u5b57\u8d44\u7d2b\u59ff\u6ecb\u59ca\u54a8\u6893\u5b5c\u6e0d\u7c7d\u6063\u9f87\u8f8e\u6dc4\u7726\u6ed3\u55de\u9aed\u5b73\u7f01\u7b2b\u9531\u79ed\u8d40\u8a3e\u89dc\u5d6b\u8d91\u7ca2\u9cbb\u9543\u8014\u8678\u9f12\u9111\u603b\u5b97\u7eb5\u8e2a\u68d5\u9b03\u7cbd\u506c\u5027\u9b37\u8159\u75ad\u8d70\u594f\u63cd\u90b9\u8bf9\u9a7a\u966c\u9139\u9cb0\u7ec4\u8db3\u65cf\u7956\u963b\u79df\u8bc5\u4fce\u955e\u83f9\u5d12\u73c7\u94bb\u6525\u7e82\u7f35\u8e9c\u6700\u5634\u7f6a\u9189\u855e\u69dc\u5c0a\u9075\u6a3d\u9cdf\u6499\u5642\u50d4\u5d9f\u505a\u4f5c\u5750\u5de6\u5ea7\u6628\u4f50\u795a\u600d\u80d9\u5511\u637d\u963c\u5c9e",
};

var map = {};
for (var initial in groups) {
    var chars = groups[initial];
    for (var i = 0; i < chars.length; i++) {
        if (map[chars[i]] === undefined) map[chars[i]] = initial;
    }
}

// Returns the A-Z bucket of the first character, or "#" when unknown.
function initialOf(text) {
    if (!text) return "#";
    var trimmed = String(text).trim();
    if (trimmed === "") return "#";
    var first = trimmed.charAt(0);
    if (/[A-Za-z]/.test(first)) return first.toUpperCase();
    return map[first] !== undefined ? map[first] : "#";
}
